<script>
 import '$lib/mission.css';
 import {onMount,tick} from 'svelte';
 import {enquiryTypes} from '$lib/contact.js';
 let busy=$state(false),errors=$state({}),failure=$state(''),success=$state(false),requestId=$state('');
 let formElement=$state(),confirmation=$state();
 onMount(()=>requestId=crypto.randomUUID());
 async function send(event){
  event.preventDefault();if(busy)return;const body=new URLSearchParams(new FormData(formElement));busy=true;failure='';errors={};
  try{const response=await fetch('/api/contact',{method:'POST',headers:{Accept:'application/json'},body});const result=await response.json();if(response.ok&&result.success){success=true;await tick();confirmation?.focus();}else{errors=result.errors||{};failure=result.message||'Your enquiry could not be sent. Please try again.';await tick();formElement.querySelector('[aria-invalid="true"]')?.focus();}}
  catch{failure='We could not connect. Please try again or call +263 777 045 891.';}finally{busy=false;}
 }
 function another(){success=false;errors={};failure='';requestId=crypto.randomUUID();}
</script>
<svelte:head><title>Contact GridUbuntu | Let's Talk Renewable Energy</title><meta name="description" content="Get in touch with GridUbuntu about renewable energy, partnerships or the platform. Call +263 777 045 891 or send a secure enquiry through our contact form."/></svelte:head>
<div class="mission-page">
 <section class="mission-hero contact-hero"><div class="mission-wrap"><p class="mission-eyebrow">CONTACT GRIDUBUNTU</p><h1>Let's start<br/><span>a conversation.</span></h1><p class="mission-lead">A question about renewable energy? An idea for your community or business? We would like to hear from you.</p></div></section>
 <section class="mission-section"><div class="mission-wrap contact-layout"><aside class="contact-information"><p class="mission-eyebrow">REACH OUR TEAM</p><h2>Good conversations<br/>start here.</h2><div class="contact-method"><span>Call us</span><a href="tel:+263777045891">+263 777 045 891</a><p>For enquiries about GridUbuntu and our work.</p></div><div class="contact-method"><span>Our focus</span><strong>Zimbabwe</strong><p>Households, small businesses and communities.</p></div><div class="client-help"><h3>Already a client?</h3><p>Sign in to view your energy information. If you need help with access, call us or select “Existing client support” in the form.</p><a class="mission-link" href="/login">Go to your portal <span aria-hidden="true">→</span></a></div></aside>
 <div class="contact-form-panel">{#if success}<div class="contact-confirmation" bind:this={confirmation} tabindex="-1" role="status"><p class="mission-eyebrow">ENQUIRY RECEIVED</p><h2>Thank you for<br/>getting in touch.</h2><p>Your message has been saved for the GridUbuntu team. We will use the contact details you provided to respond.</p><button class="mission-button" type="button" onclick={another}>Send another enquiry</button></div>{:else}<h2>Send an enquiry</h2><p class="form-intro">Tell us a little about yourself and how we can help. Fields marked * are required.</p>{#if failure}<div class="contact-error" role="alert">{failure}</div>{/if}<form bind:this={formElement} method="POST" action="/api/contact" onsubmit={send} aria-busy={busy}>
 <input type="hidden" name="request_id" value={requestId}/><div class="contact-trap" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"/></label></div>
 <fieldset disabled={busy}><div class="contact-fields"><label>Full name *<input name="name" autocomplete="name" required maxlength="120" aria-invalid={!!errors.name} aria-describedby={errors.name?'name-error':undefined}/>{#if errors.name}<small id="name-error">{errors.name}</small>{/if}</label><label>Email address *<input name="email" type="email" autocomplete="email" required maxlength="254" aria-invalid={!!errors.email} aria-describedby={errors.email?'email-error':undefined}/>{#if errors.email}<small id="email-error">{errors.email}</small>{/if}</label><label>Organisation <span class="optional">Optional</span><input name="organisation" autocomplete="organization" maxlength="120" aria-invalid={!!errors.organisation}/></label><label>Phone number <span class="optional">Optional</span><input name="phone" type="tel" autocomplete="tel" maxlength="40" aria-invalid={!!errors.phone}/></label><label class="full">What would you like to discuss? *<select name="enquiry" required aria-invalid={!!errors.enquiry} aria-describedby={errors.enquiry?'enquiry-error':undefined}><option value="">Select an enquiry type</option>{#each enquiryTypes as type}<option>{type}</option>{/each}</select>{#if errors.enquiry}<small id="enquiry-error">{errors.enquiry}</small>{/if}</label><label class="full">Your message *<textarea name="message" rows="6" required minlength="10" maxlength="4000" placeholder="Tell us what you have in mind…" aria-invalid={!!errors.message} aria-describedby="message-hint"></textarea><small id="message-hint" class:error-text={!!errors.message}>{errors.message||'Please leave out passwords, API keys and other sensitive account information.'}</small></label></div>
 <label class="contact-consent"><input type="checkbox" name="consent" value="yes" required aria-invalid={!!errors.consent}/><span>I agree that GridUbuntu may securely store this enquiry and use my contact details to respond. *</span></label>{#if errors.consent}<p class="error-text">{errors.consent}</p>{/if}<button class="mission-button submit-enquiry">{busy?'Sending…':'Send enquiry'} <span aria-hidden="true">→</span></button><p class="form-note">Your details are shared with the GridUbuntu team handling your enquiry.</p></fieldset>
 </form>{/if}</div></div></section>
</div>
<style>
 .contact-hero{padding:56px 0}.contact-layout{display:grid;grid-template-columns:.75fr 1.25fr;gap:72px;align-items:start}.contact-information h2{font-size:32px}.contact-method{border-top:1px solid #d9e2d1;margin-top:26px;padding-top:22px}.contact-method>span{display:block;color:#61725d;font-size:12px;margin-bottom:10px}.contact-method>a,.contact-method>strong{display:block;font-size:22px;font-weight:700;color:#274f31;text-decoration:none}.contact-method>a:hover{text-decoration:underline}.contact-method p{font-size:13px;line-height:1.8;color:#61725d;margin-top:12px}.client-help{margin-top:32px;background:#edf2e7;border:1px solid #d9e2d1;border-radius:10px;padding:22px}.client-help h3{font-size:16px}.client-help p{font-size:13px;color:#61725d;line-height:1.85;margin:0}.contact-form-panel{padding:32px;border:1px solid #d9e2d1;border-radius:14px;background:#fff}.contact-form-panel h2{font-size:28px;margin-bottom:14px}.form-intro{font-size:14px;color:#61725d;line-height:1.8;margin:0 0 26px}.contact-fields{display:grid;grid-template-columns:1fr 1fr;gap:22px 18px}.contact-fields label{display:flex;flex-direction:column;gap:8px;font-size:13px;font-weight:600;color:#354e32}.optional{font-weight:400;font-size:11px;color:#61725d}.contact-fields input,.contact-fields select,.contact-fields textarea{width:100%;min-width:0;border:1px solid #cddac5;border-radius:8px;padding:12px;background:#fafcf7;color:#203c2e;font:inherit;font-size:14px;font-weight:400}.contact-fields input,.contact-fields select{min-height:46px}.contact-fields textarea{resize:vertical;min-height:160px}.contact-fields [aria-invalid=true]{border-color:#984832}.contact-fields .full{grid-column:1/-1}.contact-fields small{font-size:11px;font-weight:400;line-height:1.7;color:#984832}.contact-fields #message-hint{color:#61725d}.contact-fields #message-hint.error-text{color:#984832}fieldset{padding:0;margin:0;border:0;min-width:0}.contact-consent{display:flex;align-items:flex-start;gap:12px;font-size:12px;line-height:1.8;color:#61725d;margin:24px 0}.contact-consent input{accent-color:#315a35;width:18px;height:18px;flex-shrink:0;margin-top:2px}.submit-enquiry{cursor:pointer;border:0;width:100%}.submit-enquiry:disabled{opacity:.6;cursor:wait}.form-note{font-size:11px;color:#61725d;line-height:1.8;margin:14px 0 0}.contact-trap{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}.contact-error{padding:14px;background:#fbede8;color:#893d2b;font-size:13px;line-height:1.8;border-radius:8px;margin-bottom:22px}.error-text{color:#984832;font-size:12px}.contact-confirmation{padding:24px 0;outline:none}.contact-confirmation>p:not(.mission-eyebrow){font-size:16px;line-height:1.85;color:#61725d;margin-bottom:26px}.contact-confirmation button{border:0;cursor:pointer}@media(max-width:900px){.contact-layout{grid-template-columns:1fr;gap:34px}}@media(max-width:540px){.contact-fields{grid-template-columns:1fr}.contact-form-panel{padding:24px 20px}.contact-hero{padding:40px 0}}
</style>
